mapper.select:
select jta.TRANSFER_APPLICATION_ID, jta.TRANSFER_APPLICATION_NUMBER, jta.EMPLOYEE_ID, jta.APPLICATION_DATE, ( SELECT em.name FROM fnd_employee em WHERE em.employee_id = jta.EMPLOYEE_ID ) AS EMPLOYEE_ID_N, jta.UNIT_ID , ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = jta.unit_id ) AS unit_id_n, jta.STATUS, ( SELECT meaning FROM sys_code_value_b_v v WHERE v.CODE = 'LON.CONTRACT_WITHDRAW_STATUS' AND v.code_value = jta.STATUS ) AS STATUS_N from jc_transfer_application jta
1=1
and (jta.created_by = #{authority} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{authority}))
and jta.TRANSFER_APPLICATION_NUMBER = #{transferApplicationNumber}
and jta.EMPLOYEE_ID = #{employeeId}
and jta.UNIT_ID = #{unitId}
and jta.status = #{status}
and jta.APPLICATION_DATE = #{applicationDate}
order by jta.TRANSFER_APPLICATION_ID desc
